230	    expect(clash[24]!.fighters.map((fighter) => fighter.bolt?.x)).toEqual([2384 + 1600, 7616 - 1600]);
231	    expect(clash[25]!.fighters.map((fighter) => fighter.bolt)).toEqual([null, null]);
