233	    expect(events(hit)).toEqual(["27 hit 1 flame-bolt"]);
234	    // Neither where the bolt started frame 27 nor where it would have ended it touches the Duelist's hurtbox.
235	    const hurt = worldBox(body.hurtboxes.standing, 2000, 0, 1);
236	    const from = hit[26]!.fighters[1].bolt!;
237	    expect([from.x, from.x - 1600].map((x) => overlaps(boltBox(fast.moveset, from, x), hurt))).toEqual([false, false]);
238	    // Two bolts moving apart never meet.
239	    const apart = duel(["ember", "ember"], 2000, 8000, { bolt: { ...leftBolt(5000), vx: -1600 } }, { bolt: { ...leftBolt(5400), vx: 1600 } }, fast);
240	    const after = run(apart, hold(1), fast)[1]!;
241	    expect(after.fighters.map((fighter) => fighter.bolt?.x)).toEqual([5000 - 1600, 5400 + 1600]);
