245	    // Player one is cornered at the left wall. The bolt's pushback is all absorbed by the wall...
246	    const bolted = run(duel(["duelist", "ember"], HALF, HALF + 1600), presses(40, [1, 0, U]));
247	    expect(events(bolted)).toEqual([expect.stringMatching(/hit 1 flame-bolt$/)]);
248	    expect(bolted[40]!.fighters[1].x).toBe(HALF + 1600);
249	    // ...where the same fighter's jab would have pushed it back.
250	    const jabbed = run(duel(["duelist", "ember"], HALF, HALF + 600), presses(20, [1, 0, I("light")]));
251	    expect(events(jabbed)).toEqual(["8 hit 1 jab"]);
252	    expect(jabbed[20]!.fighters[1].x).toBeGreaterThan(HALF + 600);
253	  });
254	});
