import { describe, expect, it } from "vitest";
import { baselineFrameBudgets } from "../frameBudgets.js";
import {
  DUEL_INPUT,
  DUEL_INPUT_MASK,
  duelistMoves,
  duelistMoveset,
  emberMoves,
  FEINT_REAPPEARANCE_FRAMES,
  KIT_IDS,
  kitBudgetIssues,
  MOVESET_VERSION,
  movesetVersion,
  validateDuelInputLog,
  validateDuelMove,
  validateDuelMoveset,
  smokeMoves,
  strikesWithHitbox,
  type DuelMove,
  type DuelMoveset,
} from "./index.js";

const byId = (id: string) => duelistMoveset.moves.find((move) => move.timing.id === id)!;
const withMove = (id: string, change: (move: DuelMove) => unknown): unknown => ({
  ...duelistMoveset,
  moves: duelistMoveset.moves.map((move) => (move.timing.id === id ? change(move) : move)),
});

function issuesOf(candidate: unknown): string[] {
  const result = validateDuelMoveset(candidate);
  return result.ok ? [] : result.issues;
}

describe("Duelist move data", () => {
  it("is valid and identified by MOVESET_VERSION", () => {
    expect(validateDuelMoveset(duelistMoveset).ok).toBe(true);
    expect(movesetVersion(duelistMoveset)).toBe(MOVESET_VERSION);
    expect(MOVESET_VERSION).toMatch(/^[0-9a-f]{16}$/);
  });

  it("changes its version when any datum changes", () => {
    /** Every path to a number or string in the data. */
    const leaves = (value: unknown, path: (string | number)[] = []): (string | number)[][] =>
      typeof value === "object" && value !== null ? Object.entries(value).flatMap(([key, child]) => leaves(child, [...path, key])) : [path];
    const paths = leaves(duelistMoveset);
    expect(paths.length).toBeGreaterThan(150);
    for (const path of paths) {
      const copy = JSON.parse(JSON.stringify(duelistMoveset)) as DuelMoveset;
      let parent = copy as unknown as Record<string, unknown>;
      for (const key of path.slice(0, -1)) parent = parent[key] as Record<string, unknown>;
      const last = path[path.length - 1]!;
      const value = parent[last];
      parent[last] = typeof value === "number" ? value + 1 : `${String(value)}x`;
      expect(movesetVersion(copy), path.join(".")).not.toBe(MOVESET_VERSION);
    }
    // An equal copy keeps the version: it depends on the data, not on the object.
    expect(movesetVersion(JSON.parse(JSON.stringify(duelistMoveset)) as DuelMoveset)).toBe(MOVESET_VERSION);
  });

  it("has the six normals and the two specials (§7, §9)", () => {
    expect(duelistMoves.map((move) => move.timing.id)).toEqual([
      "jab",
      "heavy-mid",
      "low-sweep",
      "launcher",
      "anti-air",
      "throw",
      "advancing-thrust",
      "counter-slash",
    ]);
    expect(duelistMoveset.commands).toEqual({
      light: "jab",
      downLight: "anti-air",
      heavy: "heavy-mid",
      downHeavy: "low-sweep",
      forwardHeavy: "launcher",
      special1: "advancing-thrust",
      special2: "counter-slash",
      throw: "throw",
    });
  });

  it("takes the jab, heavy mid, low sweep and throw timings from §8's baseline table itself", () => {
    for (const id of ["jab", "heavy-mid", "low-sweep", "throw"]) {
      expect(byId(id).timing).toBe(baselineFrameBudgets.find((row) => row.id === id));
    }
  });

  it("keeps §7's damage: a 45 jab, 100-150 for committed heavies and specials", () => {
    expect(byId("jab").damage).toBe(45);
    for (const move of duelistMoves.filter((candidate) => candidate.category === "heavy" || candidate.category === "special")) {
      expect(move.damage).toBeGreaterThanOrEqual(100);
      expect(move.damage).toBeLessThanOrEqual(150);
    }
  });

  it("charges §7's guard stamina: light 10, heavy 25, special 20", () => {
    expect(duelistMoves.map((move) => [move.timing.id, move.guardStaminaCost])).toEqual([
      ["jab", 10],
      ["heavy-mid", 25],
      ["low-sweep", 25],
      ["launcher", 25],
      ["anti-air", 10],
      ["throw", 0],
      ["advancing-thrust", 20],
      ["counter-slash", 20],
    ]);
  });

  it("keeps §7's round, stamina, combo and throw rules and §8's input buffer", () => {
    expect(duelistMoveset.rules).toMatchObject({
      roundFrames: 3600,
      overtimeFrames: 600,
      maxHealth: 1000,
      maxStamina: 100,
      dashStaminaCost: 20,
      staminaRegenDelayFrames: 60,
      staminaRegenIntervalFrames: 3,
      guardBreakStaggerFrames: 30,
      guardBreakStaminaRestore: 30,
      comboScaling: [100, 80, 65, 50, 40],
      comboCap: 5,
      throwEscapeFrames: 10,
      inputBufferFrames: 4,
      throwChordFrames: 2,
    });
  });

  it("makes the heavy's blocked spacing reachable by the jab", () => {
    const standing = duelistMoveset.fighter.hurtboxes.standing;
    const heavy = byId("heavy-mid");
    const jab = byId("jab");
    // Farthest origin distance at which the heavy still touches a standing hurtbox, plus its block pushback.
    const leftBehind = heavy.hitbox.x + heavy.hitbox.w - standing.x - 1 + heavy.blockPushback;
    expect(leftBehind).toBeLessThan(jab.hitbox.x + jab.hitbox.w - standing.x);
    expect([heavy.blockPushback, jab.hitbox.x + jab.hitbox.w]).toEqual([64, 1024]);
  });
});

describe("fruit kits (§9)", () => {
  it("hold the Duelist, Ember and Smoke kits, each two valid specials in the one moveset", () => {
    expect(KIT_IDS).toEqual(["duelist", "ember", "smoke"]);
    expect(duelistMoveset.kits).toEqual({
      duelist: { special1: "advancing-thrust", special2: "counter-slash" },
      ember: { special1: "flame-bolt-cast", special2: "rising-flare" },
      smoke: { special1: "feint-dash", special2: "smoke-screen" },
    });
    expect(duelistMoveset.moves).toEqual([...duelistMoves, ...emberMoves, ...smokeMoves]);
    for (const kit of KIT_IDS) {
      for (const id of [duelistMoveset.kits[kit].special1, duelistMoveset.kits[kit].special2]) {
        const move = byId(id);
        expect(validateDuelMove(move), id).toMatchObject({ ok: true });
        expect(move.category).toBe("special");
      }
    }
    // The Duelist's commands keep its specials, so a duel without kits is unchanged.
    expect([duelistMoveset.commands.special1, duelistMoveset.commands.special2]).toEqual(["advancing-thrust", "counter-slash"]);
  });

  it("give each move one effect: the flame bolt casts a projectile, the screen a zone, the feint only moves", () => {
    expect(Object.fromEntries(duelistMoveset.moves.map((move) => [move.timing.id, move.effect]))).toMatchObject({
      jab: "strike",
      throw: "strike",
      "rising-flare": "strike",
      "flame-bolt-cast": "projectile",
      "smoke-screen": "zone",
      "feint-dash": "feint",
    });
    expect(duelistMoveset.moves.filter((move) => !strikesWithHitbox(move)).map((move) => move.timing.id)).toEqual(["flame-bolt-cast", "feint-dash", "smoke-screen"]);
  });

  it("keep every new special within §8's budgets (docs/fruit-kits.md's named checks)", () => {
    expect(kitBudgetIssues(duelistMoveset)).toEqual([]);
    const cast = byId("flame-bolt-cast");
    const projectileRow = baselineFrameBudgets.find((row) => row.id === "projectile-special")!;
    expect(cast.timing.startup).toBeGreaterThanOrEqual(projectileRow.startup);
    expect(cast.timing.recovery).toBeGreaterThanOrEqual(projectileRow.recovery);
    for (const id of ["rising-flare", "feint-dash", "smoke-screen"]) expect(byId(id).timing.startup, id).toBeGreaterThanOrEqual(byId("counter-slash").timing.startup);
    expect(byId("rising-flare").timing.recovery).toBeGreaterThanOrEqual(30);
    expect(byId("feint-dash").timing.recovery).toBeGreaterThanOrEqual(FEINT_REAPPEARANCE_FRAMES);
    const flare = byId("rising-flare");
    expect(flare.blockstun - flare.timing.active - flare.timing.recovery).toBe(flare.timing.onBlock.kind === "frames" ? flare.timing.onBlock.advantage : NaN);
    expect(cast.projectile!.blockstun - cast.timing.active - cast.timing.recovery).toBeLessThan(0);
  });

  it.each([
    ["a bolt starting up faster than §8's projectile row", "flame-bolt-cast", (move: DuelMove) => ({ ...move, timing: { ...move.timing, startup: 21 } }), "projectile-floors"],
    ["a bolt recovering faster than §8's projectile row", "flame-bolt-cast", (move: DuelMove) => ({ ...move, timing: { ...move.timing, recovery: 29 } }), "projectile-floors"],
    ["a bolt safe at point blank", "flame-bolt-cast", (move: DuelMove) => ({ ...move, projectile: { ...move.projectile!, blockstun: 60 } }), "bolt-block-advantage"],
    ["a special faster than the Duelist's fastest", "smoke-screen", (move: DuelMove) => ({ ...move, timing: { ...move.timing, startup: 7 } }), "special-startup"],
    ["a reversal recovering in under 30 frames", "rising-flare", (move: DuelMove) => ({ ...move, timing: { ...move.timing, recovery: 29, onBlock: { kind: "frames" as const, advantage: -23 } } }), "anti-air-recovery"],
  ])("flags %s", (_label, id, change, check) => {
    const moveset = withMove(id, change) as DuelMoveset;
    expect(kitBudgetIssues(moveset).map((issue) => issue.split(":")[0])).toEqual([check]);
  });

  it("refuses a kit naming an unknown move or a move that is not a special", () => {
    expect(issuesOf({ ...duelistMoveset, kits: { ...duelistMoveset.kits, ember: { special1: "fireball", special2: "rising-flare" } } })).toEqual([
      'kits.ember.special1: unknown move "fireball"',
    ]);
    // The bolt's id names no move.
    expect(issuesOf({ ...duelistMoveset, kits: { ...duelistMoveset.kits, ember: { special1: "flame-bolt", special2: "rising-flare" } } })).toEqual([
      'kits.ember.special1: unknown move "flame-bolt"',
    ]);
    expect(issuesOf({ ...duelistMoveset, kits: { ...duelistMoveset.kits, smoke: { special1: "jab", special2: "smoke-screen" } } })).toEqual([
      'kits.smoke.special1: "jab" is not a special',
    ]);
    expect(issuesOf({ ...duelistMoveset, kits: { duelist: duelistMoveset.kits.duelist, ember: duelistMoveset.kits.ember } })).not.toEqual([]);
  });

  it("refuses Duelist commands that differ from the Duelist kit", () => {
    expect(issuesOf({ ...duelistMoveset, commands: { ...duelistMoveset.commands, special1: "counter-slash" } })).toEqual([
      "commands.special1: the special1 command is the Duelist kit's",
    ]);
  });

  it("refuses a projectile move without projectile data, a zone move without zone data, and data on the wrong effect", () => {
    const cast = byId("flame-bolt-cast");
    const screen = byId("smoke-screen");
    const issues = (move: unknown) => {
      const result = validateDuelMove(move);
      return result.ok ? [] : result.issues;
    };
    const { projectile: _projectile, ...noProjectile } = cast;
    const { zone: _zone, ...noZone } = screen;
    expect(issues(noProjectile)).toEqual(["projectile: a projectile move, and only a projectile move, has projectile data"]);
    expect(issues(noZone)).toEqual(["zone: a zone move, and only a zone move, has zone data"]);
    expect(issues({ ...byId("jab"), projectile: cast.projectile })).toEqual(["projectile: a projectile move, and only a projectile move, has projectile data"]);
    expect(issues({ ...cast, zone: screen.zone })).toEqual(["zone: a zone move, and only a zone move, has zone data"]);
    expect(issuesOf(withMove("flame-bolt-cast", () => noProjectile))).toContain("moves.8.projectile: a projectile move, and only a projectile move, has projectile data");
    expect(issuesOf(withMove("smoke-screen", () => noZone))).toContain("moves.11.zone: a zone move, and only a zone move, has zone data");
  });

  it("refuses a non-striking move that deals damage, and a strike without damage", () => {
    const issues = (move: unknown) => {
      const result = validateDuelMove(move);
      return result.ok ? [] : result.issues;
    };
    expect(issues({ ...byId("feint-dash"), damage: 30 })).toEqual(["damage: a feint move never strikes, so its damage is 0"]);
    expect(issues({ ...byId("smoke-screen"), effect: "strike" })).not.toEqual([]);
    expect(issues({ ...byId("jab"), effect: "feint" })).not.toEqual([]);
  });

  it("refuses a feint whose cancel opens inside its reappearance, and a cancel on anything but a feint", () => {
    const feint = byId("feint-dash");
    const issues = (move: unknown) => {
      const result = validateDuelMove(move);
      return result.ok ? [] : result.issues;
    };
    const reappeared = feint.timing.startup + feint.timing.active + FEINT_REAPPEARANCE_FRAMES;
    expect(issues({ ...feint, cancel: { ...feint.cancel!, opens: reappeared } })[0]).toMatch(/^cancel\.opens: a feint's cancel opens after its reappearance/);
    expect(issues({ ...feint, cancel: { ...feint.cancel!, opens: reappeared + 1 } })).toEqual([]);
    expect(issues({ ...feint, timing: { ...feint.timing, recovery: FEINT_REAPPEARANCE_FRAMES - 1 }, cancel: undefined })[0]).toMatch(/^timing\.recovery/);
    expect(issues({ ...feint, cancel: { ...feint.cancel!, into: ["special1"] } })).not.toEqual([]);
    expect(issues({ ...byId("jab"), cancel: feint.cancel })).toEqual(["cancel: only a feint can be cancelled"]);
  });

  it("refuses a projectile id that is also a move id or another bolt's", () => {
    expect(issuesOf(withMove("flame-bolt-cast", (move) => ({ ...move, projectile: { ...move.projectile!, id: "jab" } })))).toEqual([
      "moves.8.projectile.id: jab: a projectile id must be unique",
    ]);
  });
});

